#!/bin/bash
ENV_FILE=~/michielstokman_ai_part/.env
B64_STRING=""

# Remove existing key if present
sed -i '/FIREBASE_SERVICE_ACCOUNT_JSON/d' $ENV_FILE

# Append new key
echo "FIREBASE_SERVICE_ACCOUNT_JSON=$B64_STRING" >> $ENV_FILE

# Restart API
docker compose -f ~/michielstokman_ai_part/docker-compose.yml restart api
